#!/usr/bin/env python3
"""paths-to-call-site.py <shift>: each row has a HOLDER of its own (a literal, a class, an instance, an array, a Map, a variable of a closure or of the module) that holds a function A in plain sight, and ONE CALL SITE that calls what the holder holds. The site is run, then ONE DEED puts something else B there by a way the analysis must model or give up on, and the site is run again; then things are put back and it is run a third time. B rotates through twelve kinds of callee (see paths-to-read-site.py). Untyped JavaScript: every line as plain Bun's."""
import sys
shift = int(sys.argv[1]) if len(sys.argv) > 1 else 0
import os
lean = bool(os.environ.get('LEAN'))
KINDS = ['(p, q) => "B" + p + q + k', 'function (p) { return "B" + p + arguments.length + k; }', '((p, q, r) => "B" + p + q + r + k).bind(null, 7)', 'Math.max', 'new Proxy((p) => "B" + p + k, {})', 'async (p) => "B" + p', 'function* (p) { yield p; }', 'class { constructor(p) { this.p = p; } }', '({ m(p) { return "B" + p + k; } }).m', 'String', '(p = 5, ...rest) => "B" + p + rest.length + k', 'Object.assign((p) => "B" + p + k, { tag: 1 })', '5', 'undefined', '{ call: 1 }']
L = 'const h = { m: a, other: 1 };'; CALL = 'h.m(1, 2)'
ROWS = [
 # what, the holder, the call, the deed, the undoing
 ('a store by name', L, CALL, 'h.m = b', 'h.m = a'), ('a store by a computed key', L, CALL, 'h[["m"].join("")] = b', 'h.m = a'), ('a store by a key out of a loop', L, CALL, 'for (const key of Object.keys(h)) if (key.length === 1) h[key] = b', 'h.m = a'), ('for in', L, CALL, 'for (const key in h) if (key === "m") h[key] = b', 'h.m = a'),
 ('Object.assign', L, CALL, 'Object.assign(h, { m: b })', 'h.m = a'), ('Object.assign from a computed literal', L, CALL, 'Object.assign(h, { [["m"].join("")]: b })', 'h.m = a'), ('Object.assign from entries', L, CALL, 'Object.assign(h, Object.fromEntries([["m", b]]))', 'h.m = a'), ('Reflect.set', L, CALL, 'Reflect.set(h, "m", b)', 'h.m = a'),
 ('defineProperty: a value', L, CALL, 'Object.defineProperty(h, "m", { value: b, writable: true, configurable: true, enumerable: true })', 'h.m = a'), ('defineProperty: a getter', L, CALL, 'Object.defineProperty(h, "m", { get: () => b, configurable: true, enumerable: true })', 'Object.defineProperty(h, "m", { value: a, writable: true, configurable: true, enumerable: true })'), ('defineProperties', L, CALL, 'Object.defineProperties(h, { m: { value: b, writable: true, configurable: true, enumerable: true } })', 'h.m = a'), ('Reflect.defineProperty', L, CALL, 'Reflect.defineProperty(h, "m", { value: b, writable: true, configurable: true, enumerable: true })', 'h.m = a'),
 ('deleted: the prototype answers', 'const h = Object.setPrototypeOf({ m: a }, { m: b });', CALL, 'delete h.m', 'h.m = a'), ('deleted: nothing answers', L, CALL, 'delete h.m', 'h.m = a'), ('the prototype is swapped', 'const h = Object.create({ m: a });', CALL, 'Object.setPrototypeOf(h, { m: b })', 'Object.setPrototypeOf(h, { m: a })'), ('__proto__ is stored to', 'const h = Object.create({ m: a });', CALL, 'h.__proto__ = { m: b }', 'h.__proto__ = { m: a }'), ('the prototype itself is changed', 'const up = { m: a }; const h = Object.create(up);', CALL, 'up.m = b', 'up.m = a'), ('shadowed on the heir', 'const h = Object.create({ m: a });', CALL, 'h.m = b', 'delete h.m'),
 ('through an alias', L + ' const alias = [h][0];', CALL, 'alias.m = b', 'h.m = a'), ('through an alias in a Map', L + ' const map = new Map([["h", h]]);', CALL, 'map.get("h").m = b', 'h.m = a'), ('through a closure', L + ' const set = x => { h.m = x; };', CALL, 'set(b)', 'set(a)'), ('through this', 'const h = { m: a, replace(x) { this.m = x; } };', CALL, 'h.replace(b)', 'h.replace(a)'), ('through a method borrowed', L + ' const tool = { replace(x) { this.m = x; } };', CALL, 'tool.replace.call(h, b)', 'h.m = a'), ('through a setter', 'const h = { m: a, set both(x) { this.m = x; } };', CALL, 'h.both = b', 'h.both = a'), ('through a proxy of it', L, CALL, 'new Proxy(h, {}).m = b', 'h.m = a'), ('through a pattern', L, CALL, '({ x: h.m } = { x: b })', 'h.m = a'), ('through an array pattern', L, CALL, '[h.m] = [b]', 'h.m = a'), ('a logical assignment', 'const h = { m: a, n: null };', '(h.n ?? h.m)(1, 2)', 'h.n ??= b', 'h.n = null'),
 ('a method of a class, on the prototype', 'class K { m(p, q) { return a(p, q); } } const h = new K();', CALL, 'K.prototype.m = b', 'delete K.prototype.m; K.prototype.m = function (p, q) { return a(p, q); }'), ('a method of a class, shadowed on the instance', 'class K { m(p, q) { return a(p, q); } } const h = new K();', CALL, 'h.m = b', 'delete h.m'), ('a static method', 'class K { static m(p, q) { return a(p, q); } } const h = K;', CALL, 'K.m = b', 'K.m = a'), ('a field that holds it', 'class K { m = a; } const h = new K();', CALL, 'h.m = b', 'h.m = a'), ('the instance gets another class', 'class K { m(p, q) { return a(p, q); } } class O { } O.prototype.m = b; const h = new K();', CALL, 'Object.setPrototypeOf(h, O.prototype)', 'Object.setPrototypeOf(h, K.prototype)'), ('super, and the base is swapped', 'class Base { m(p, q) { return a(p, q); } } class K extends Base { m(p, q) { return super.m(p, q); } } const h = new K();', CALL, 'Object.setPrototypeOf(K.prototype, { m: b })', 'Object.setPrototypeOf(K.prototype, Base.prototype)'), ('an heir overrides', 'class K { m(p, q) { return a(p, q); } run() { return this.m(1, 2); } } class Heir extends K { } let h = new K();', 'h.run()', 'Heir.prototype.m = b; h = new Heir()', 'h = new K()'),
 ('an array: an index', 'const h = [a, a];', 'h[1](1, 2)', 'h[1] = b', 'h[1] = a'), ('an array: push and the last', 'const h = [a];', 'h[h.length - 1](1, 2)', 'h.push(b)', 'h.pop()'), ('an array: reverse', 'const h = [a, b];', 'h[0](1, 2)', 'h.reverse()', 'h.reverse()'), ('an array: sort', 'const h = [a, b];', 'h[0](1, 2)', 'h.sort(() => 1).sort(() => -1); h.reverse()', 'if (h[0] !== a) h.reverse()'), ('an array: splice', 'const h = [a];', 'h[0](1, 2)', 'h.splice(0, 0, b)', 'h.splice(0, 1)'), ('an array: fill', 'const h = [a, a];', 'h[1](1, 2)', 'h.fill(b)', 'h.fill(a)'), ('an array: copyWithin', 'const h = [a, b];', 'h[0](1, 2)', 'h.copyWithin(0, 1)', 'h[0] = a'), ('an array: unshift', 'const h = [a];', 'h[0](1, 2)', 'h.unshift(b)', 'h.shift()'), ('an array: length and a hole', 'const h = [a];', 'h[0](1, 2)', 'h.length = 0; h.length = 1', 'h[0] = a'), ('an array walked by forEach', 'const h = [a];', '(() => { let r; h.forEach(f => { r = f(1, 2); }); return r; })()', 'h[0] = b', 'h[0] = a'), ('an array walked by for of', 'const h = [a];', '(() => { let r; for (const f of h) r = f(1, 2); return r; })()', 'h[0] = b', 'h[0] = a'), ('an array and map', 'const h = [a];', 'h.map(f => f(1, 2))[0]', 'h[0] = b', 'h[0] = a'),
 ('a Map', 'const h = new Map([["m", a]]);', 'h.get("m")(1, 2)', 'h.set("m", b)', 'h.set("m", a)'), ('a Map: another key object that is equal', 'const h = new Map([[1, a]]);', 'h.get(1)(1, 2)', 'h.set(1.0, b)', 'h.set(1, a)'), ('a Map: deleted', 'const h = new Map([["m", a]]);', 'h.get("m")(1, 2)', 'h.delete("m")', 'h.set("m", a)'), ('a Map: cleared and filled', 'const h = new Map([["m", a]]);', 'h.get("m")(1, 2)', 'h.clear(); h.set("m", b)', 'h.set("m", a)'), ('a Set', 'const h = new Set([a]);', '[...h][h.size - 1](1, 2)', 'h.add(b)', 'h.delete(b)'), ('a WeakMap', 'const key = {}; const h = new WeakMap([[key, a]]);', 'h.get(key)(1, 2)', 'h.set(key, b)', 'h.set(key, a)'),
 ('a variable stored to by another closure', 'let h = a; const set = x => { h = x; };', 'h(1, 2)', 'set(b)', 'set(a)'), ('a variable stored to in a pattern', 'let h = a;', 'h(1, 2)', '[h] = [b]', 'h = a'), ('a variable stored to in a loop head', 'let h = a;', 'h(1, 2)', 'for (h of [b]);', 'h = a'), ('a variable stored to in a catch', 'let h = a;', 'h(1, 2)', 'try { throw b; } catch (e) { h = e; }', 'h = a'), ('a parameter stored to', 'let h = a;', '((f) => { if (h !== a) f = h; return f(1, 2); })(a)', 'h = b', 'h = a'), ('globalThis', 'globalThis.h$ = a;', 'globalThis.h$(1, 2)', 'globalThis.h$ = b', 'globalThis.h$ = a'), ('globalThis by a bare name', 'globalThis.g$ = a;', 'g$(1, 2)', 'globalThis["g$"] = b', 'globalThis.g$ = a'),
 ('a getter that chooses', 'let which = a; const h = { get m() { return which; } };', CALL, 'which = b', 'which = a'), ('a bound function and its target', 'const box = { f: a }; const h = { m: (...x) => box.f(...x) };', CALL, 'box.f = b', 'box.f = a'), ('frozen first: the store fails', 'const h = Object.freeze({ m: a });', CALL, 'try { h.m = b; } catch (e) { got.push("T:" + e.name); }', '0'), ('a spread copy with another', 'let h = { m: a };', CALL, 'h = { ...h, m: b }', 'h = { m: a }'), ('JSON revives another', 'let h = { m: a };', CALL, 'h = JSON.parse("{\\"m\\":1}", (key, v) => (key === "m" ? b : v))', 'h = { m: a }'), ('structured by Object.entries', 'let h = { m: a };', CALL, 'h = Object.fromEntries(Object.entries(h).map(([key]) => [key, b]))', 'h = { m: a }'), ('a symbol as the name', 'const s = Symbol(); const h = { [s]: a };', 'h[s](1, 2)', 'h[s] = b', 'h[s] = a'), ('a number as the name', 'const h = { 7: a };', 'h[7](1, 2)', 'h["7"] = b', 'h[7] = a'), ('optional call', L, 'h.m?.(1, 2)', 'h.m = b', 'h.m = a'), ('call, apply, Reflect.apply of what is held', L, '[h.m.call(null, 1, 2), h.m.apply(null, [1, 2]), Reflect.apply(h.m, null, [1, 2])].join()', 'h.m = b', 'h.m = a'), ('new of what is held', 'const h = { m: function (p) { this.v = a(p, 2); } };', 'new h.m(1).v', 'h.m = typeof b === "function" ? b : h.m', 'h.m = function (p) { this.v = a(p, 2); }'),
]
if lean: KINDS = KINDS[:2] + [KINDS[8], KINDS[10], 'function named(p, q) { return "B" + q + p + k; }']
print('const show = v => (v === null ? "null" : typeof v === "object" ? (Array.isArray(v) ? "[" + v.join() + "]" : "{" + Object.keys(v).join() + "}") : typeof v + ":" + String(v));')
n = 0
for what, holder, call, deed, undo in ROWS:
    n += 1
    if lean:
        s = 'function row$() { const k = $; let got = ""; const a = (p, q) => "A" + p + q + k; const b = %s; %s const site = () => { got += %s + " "; }; site(); site(); %s; site(); site(); %s; site(); return got; }\n{ let text; try { text = row$(); } catch { text = "THROWS"; } console.log("%d %s: " + text); }\n' % (KINDS[(n + shift) % len(KINDS)], holder, call, deed.replace('got.push("T:" + e.name)', 'got += "T "'), undo, n, what.replace('"', "'"))
    else:
      s = 'function row$() { const k = $; const got = []; const a = (p, q) => "A" + p + q + k; const b = %s; %s const site = () => { try { got.push(show(%s)); } catch (e) { got.push("T:" + e.name); } }; site(); site(); try { %s; } catch (e) { got.push("THROWS " + e.name); } site(); site(); try { %s; } catch (e) { got.push("undo THROWS " + e.name); } site(); return got.join(" "); }\nconsole.log("%d %s: " + row$());\n' % (KINDS[(n + shift) % len(KINDS)], holder, call, deed, undo, n, what.replace('"', "'"))
    print(s.replace('$', str(n)), end='')
